from pwn import remote

def test_server_codes():
    host = 'rev.chal.csaw.io'
    port = 4444

    codes_to_try = ['1', '2', '3', '123', '456', 'guess1', 'code2']

    with remote(host, port) as conn:
        responses = {}
        for code in codes_to_try:
            conn.recvuntil(b"Do you know the secret code?")  # Wait for the server's prompt
            conn.sendline(code)  # Send the code
            response = conn.recvline().strip()  # Read server's response
            responses[code] = response.decode('utf-8', errors='ignore')

    return responses

def main():
    responses = test_server_codes()
    with open("/home/ctfplayer/server_responses.txt", "w") as f:
        for code, response in responses.items():
            f.write(f"Code: {code} -> Response: {response}\n")

if __name__ == "__main__":
    main()

